package main
import("fmt";"os";"encoding/json";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/nanz";"github.com/minz/minzc/pkg/pipeline")
func main(){source,err:=os.ReadFile("../examples/nanz/grace_seeded_sum.nanz");if err!=nil{panic(err)};wdata,err:=os.ReadFile("/tmp/minz-seeded-artifacts/workload.json");if err!=nil{panic(err)};var w hir.ProfileWorkload;if err=json.Unmarshal(wdata,&w);err!=nil{panic(err)};m,err:=nanz.Parse(string(source),"seeded.nanz");if err!=nil{panic(err)};run,err:=hir.RunLoopProfile(m,w);if err!=nil{panic(err)};decisions:=[]hir.ProfileDecision{};for _,s:=range run.Profile.Sites.Sites{decisions=append(decisions,hir.ProfileDecision{SiteID:s.ID,Variant:"pointer-walk",Compatibility:run.Profile.Compatibility})};m.GraceRulePolicy=map[string]bool{"hir-constant-if":false,"hir-invariant-base":false};if err=hir.ApplyProfileDecisions(m,decisions);err!=nil{panic(err)};steps,err:=pipeline.CompileHIRSteps(m,pipeline.Options{AssertMode:"none",UseHIRGrace:true});if err!=nil{panic(err)};for n,s:=range map[string]string{"pointer.a80":steps.Assembly,"pointer.raw.mir":steps.MIR2Raw,"pointer.opt.mir":steps.MIR2Opt}{if err=os.WriteFile("/tmp/minz-seeded-artifacts/"+n,[]byte(s),0644);err!=nil{panic(err)}};fmt.Println("exported seeded pointer candidate")}
